 await h.command('tenancy.transfer',{tenancyId:leaseA.id,unitId:lower.id,moveIn:'2026-01-15'},{status:409})
 await h.command('tenancy.end',{tenancyId:leaseB.id,moveOut:'2025-12-31',reason:'Moved out early with notice'})
